package com.englishhero.identity.admin;
import com.englishhero.identity.*;
import com.englishhero.web.BusinessException;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.englishhero.identity.admin.AdminUserDtos.*;
@Service
public class AdminUserService {
 private final AdminUserMapper mapper;private final IdentityService identities;
 public AdminUserService(AdminUserMapper mapper,IdentityService identities){this.mapper=mapper;this.identities=identities;}
 long requireAdmin(SessionPrincipal actor){if(actor==null)throw new BusinessException(401,"UNAUTHENTICATED","请先登录");identities.current(actor);if(!mapper.roles(actor.userId()).contains("ADMIN"))throw new BusinessException(403,"FORBIDDEN","没有管理权限");return actor.userId();}
 User dto(AdminUserMapper.Row r,long actor){var roles=mapper.roles(r.id());return new User(Long.toString(r.id()),r.username(),r.displayName(),roles,r.enabled(),r.version(),r.createdAt(),r.id()==actor||roles.contains("ADMIN"));}
 @Transactional(readOnly=true)public Page<User> list(SessionPrincipal actor,String keyword,String status,String role,int page,int size){long uid=requireAdmin(actor);String q=AdminUserRules.text(keyword,"keyword",100,false);AdminUserRules.option(status,"status","ALL","ENABLED","DISABLED");AdminUserRules.option(role,"role","ALL","USER","ADMIN");if(page<1||page>1000000)throw BusinessException.invalid("page","页码无效");if(size<1||size>50)throw BusinessException.invalid("pageSize","每页1–50条");StringBuilder where=new StringBuilder(" WHERE 1=1");List<Object> args=new ArrayList<>();if(!q.isEmpty()){where.append(" AND (CAST(u.id AS CHAR)=? OR u.username LIKE ? ESCAPE '!' OR u.display_name LIKE ? ESCAPE '!')");String literal="%"+q.replace("!","!!").replace("%","!%").replace("_","!_")+"%";args.addAll(List.of(q,literal,literal));}if(!status.equals("ALL")){where.append(" AND u.enabled=?");args.add(status.equals("ENABLED"));}if(!role.equals("ALL")){where.append(role.equals("ADMIN")?" AND EXISTS":" AND NOT EXISTS");where.append(" (SELECT 1 FROM identity_user_role r WHERE r.user_id=u.id AND r.role='ADMIN')");}long total=mapper.sql().queryForObject("SELECT COUNT(*) FROM identity_user u"+where,Long.class,args.toArray());args.add(size);args.add((page-1)*size);var ids=mapper.sql().queryForList("SELECT u.id FROM identity_user u"+where+" ORDER BY u.id DESC LIMIT ? OFFSET ?",Long.class,args.toArray());return new Page<>(ids.stream().map(id->dto(mapper.row(id,false),uid)).toList(),page,size,total);}
 @Transactional(readOnly=true)public Detail detail(SessionPrincipal actor,String id){long uid=requireAdmin(actor);var r=mapper.row(AdminUserRules.id(id,"id"),true);var u=dto(r,uid);return new Detail(u.id(),u.username(),u.displayName(),u.roles(),u.enabled(),u.version(),u.createdAt(),u.protectedAccount(),mask(r.email()),r.emailVerified());}
 static String mask(String email){if(email==null||!email.contains("@"))return "未绑定";String[] parts=email.split("@",2);String domain=parts[1];int dot=domain.lastIndexOf('.');return parts[0].substring(0,1)+"***@"+domain.substring(0,1)+"***"+(dot>=0?domain.substring(dot):"");}
 @Transactional(readOnly=true)public AuditPage audit(SessionPrincipal actor,String userId,String cursor,int size){requireAdmin(actor);if(size<1||size>50)throw BusinessException.invalid("pageSize","每页1–50条");long boundary=cursor==null||cursor.isBlank()?Long.MAX_VALUE:AdminUserRules.id(cursor,"cursor");List<Object> args=new ArrayList<>();String where=" WHERE a.id<?";args.add(boundary);if(userId!=null&&!userId.isBlank()){where+=" AND a.target_id=?";args.add(AdminUserRules.id(userId,"userId"));}args.add(size+1);var rows=mapper.sql().query("SELECT a.id,a.actor_id,a.target_id,a.before_enabled,a.after_enabled,a.reason,a.created_at,u.username actor_name,t.username target_name FROM admin_user_audit a JOIN identity_user u ON u.id=a.actor_id JOIN identity_user t ON t.id=a.target_id"+where+" ORDER BY a.id DESC LIMIT ?",(r,n)->new Audit(r.getString("id"),new Party(r.getString("actor_id"),r.getString("actor_name")),new Party(r.getString("target_id"),r.getString("target_name")),r.getBoolean("before_enabled"),r.getBoolean("after_enabled"),r.getString("reason"),r.getTimestamp("created_at").toInstant()),args.toArray());boolean more=rows.size()>size;return new AuditPage(List.copyOf(rows.subList(0,Math.min(size,rows.size()))),more?rows.get(size-1).id():null,more);}
}
